#!/bin/bash
# list.sh [--room ROOM] [DATE]: bookings, one per line "DATE START-END ROOM WHO", sorted. src/remind.sh reads this.
set -u
BOOKINGS=${BOOKINGS:-data/bookings.tsv}
[ -r "$BOOKINGS" ] || { echo "bookings file not found: $BOOKINGS" >&2; exit 2; }
room=
if [ "${1:-}" = --room ]; then room=$2; shift 2; fi
grep -v '^#' "$BOOKINGS" | awk -F'\t' -v d="${1:-}" -v r="$room" 'NF && (d == "" || $2 == d) && (r == "" || $1 ~ r) { printf "%s %s-%s %s %s\n", $2, $3, $4, $1, $5 }' | sort

input.command:
cat > spec/list_room.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\naoi\t2026-01-02\t12:00\t13:00\tz\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = "$(printf '2026-01-01 10:00-11:00 aoi x\n2026-01-02 12:00-13:00 aoi z')" ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room ao)" ] || { echo "list --room matched a prefix"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-02)" = '2026-01-02 12:00-13:00 aoi z' ] || { echo "list --room with date"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room kaede 2026-01-02)" = '' ] || { echo "list --room with date, no match"; fail=1; }
BOOKINGS=$t bash src/list.sh --room > /dev/null 2> "$t.err"; [ $? = 2 ] || { echo "list --room without value: exit"; fail=1; }
grep -qx 'usage: list.sh \[--room ROOM\] \[DATE\]' "$t.err" || { echo "list --room without value: usage"; fail=1; }
BOOKINGS=$t bash src/list.sh 2026/11/10 > /dev/null 2> "$t.err"; [ $? = 2 ] || { echo "list bad date: exit"; fail=1; }
grep -qx 'bad date: 2026/11/10 (expected YYYY-MM-DD)' "$t.err" || { echo "list bad date: message"; fail=1; }
rm -f "$t" "$t.err"; exit $fail
EOF
python3 - <<'EOF' 2>/dev/null || sed -i 's|`bash src/list.sh \[日付\]` で一覧を出す|`bash src/list.sh [--room <部屋>] [日付]` で一覧を出す（`--room` は部屋名の完全一致で絞る）|' README.md
EOF
cat README.md; bash spec/list_room.spec.sh; echo "spec rc=$?"; bash spec/list.spec.sh; echo "list rc=$?"
